---------Magnitude analysis
-----------This focuses on the impact and importance of the key relevant dimensions to the entire business 
-----The insight here include revenue generated by each country and category on the total scale as well as the average scale
------Brand by category
select
    category,
    count(brand) Brand_count
from products
group by category
order by count(brand) desc 


-----Revenue by Country
select
    c.country,
    round(sum(t.gross_revenue),2) gross_revenue
from customers  c
    left join transactions t
    on c.customer_id = t.customer_id
    group by country
    order by count(gross_revenue) desc 




-----Revenue by category
SELECT
    p.category,
    ROUND(SUM(t.gross_revenue), 2) AS gross_revenue
FROM products p
LEFT JOIN transactions t
    ON p.product_id = t.product_id
GROUP BY p.category
ORDER BY SUM(t.gross_revenue) DESC;



-----Revenue by category
SELECT
    p.category,
    ROUND(SUM(t.gross_revenue), 2) AS gross_revenue
FROM products p
LEFT JOIN transactions t
    ON p.product_id = t.product_id
GROUP BY p.category
ORDER BY SUM(t.gross_revenue) DESC;


---Average revenue by category
SELECT
    p.category,
    ROUND(avg(t.gross_revenue), 2) AS avg_revenue
FROM products p
LEFT JOIN transactions t
    ON p.product_id = t.product_id
GROUP BY p.category
ORDER BY avg(t.gross_revenue) DESC;


--Order count by Countries
SELECT
    c.country,
    COUNT(t.transaction_id) AS order_count,
    CONCAT(
        CAST(100.0 * COUNT(t.transaction_id) / SUM(COUNT(t.transaction_id)) OVER () AS DECIMAL(5,2)),'%'
    ) AS order_percentage
FROM customers c
JOIN transactions t
    ON c.customer_id = t.customer_id
GROUP BY c.country
ORDER BY order_count DESC;



----Customer revenue with -tives
SELECT 
    c.customer_id,
    ROUND(SUM(t.gross_revenue), 2) AS gross_revenue
FROM customers c
LEFT JOIN transactions t
    ON c.customer_id = t.customer_id
    where gross_revenue is not null
GROUP BY c.customer_id
ORDER BY SUM(t.gross_revenue) DESC;



----Customer revenue fixed
SELECT
    c.customer_id,
    ROUND(SUM(COALESCE(CASE WHEN t.gross_revenue < 0 THEN 0 
       ELSE t.gross_revenue 
       END, 
 0)), 2) AS gross_revenue
FROM customers c
LEFT JOIN transactions t
    ON c.customer_id = t.customer_id
GROUP BY c.customer_id
ORDER BY SUM(
    COALESCE(CASE WHEN t.gross_revenue < 0 THEN 0 
            ELSE t.gross_revenue 
        END, 0)
) DESC;
